// Standard-library checks of the actual page script, without network access.
const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const elements = {key: {value: ''}, result: {textContent: ''}, all: {hidden: true}, mine: {}};
const pending = [];
const context = vm.createContext({
  document: {getElementById: id => elements[id]},
  fetch: (path, options) => new Promise(resolve => pending.push({path, options, resolve})),
});
const script = fs.readFileSync('index.html', 'utf8').match(/<script>([\s\S]*?)<\/script>/)[1];
vm.runInContext(script, context);
function reply(call, ok, value) {call.resolve({ok, json: async () => value});}
async function run() {
  elements.key.value = 'demo-organizer';
  let change = elements.key.oninput();
  reply(pending.shift(), true, {role: 'organizer'});
  await change;
  assert.equal(elements.all.hidden, false);
  let show = elements.all.onclick();
  let oldList = pending.shift();
  elements.key.value = 'demo-alice';
  change = elements.key.oninput();
  assert.equal(elements.all.hidden, true);
  assert.equal(elements.result.textContent, '');
  reply(oldList, true, [{id: 'r-a'}, {id: 'r-b'}]);
  await show;
  assert.equal(elements.result.textContent, '');
  reply(pending.shift(), true, {role: 'member'});
  await change;
  show = elements.mine.onclick();
  let call = pending.shift();
  assert.equal(call.path, '/api/mine');
  assert.equal(call.options.headers['X-Demo-Key'], 'demo-alice');
  reply(call, true, [{id: 'r-a'}]);
  await show;
  assert.deepEqual(JSON.parse(elements.result.textContent), [{id: 'r-a'}]);
  elements.key.value = 'demo-organizer';
  const staleChange = elements.key.oninput();
  const staleRole = pending.shift();
  elements.key.value = '';
  change = elements.key.oninput();
  reply(pending.shift(), false, {error: '请输入有效的演示凭据'});
  await change;
  reply(staleRole, true, {role: 'organizer'});
  await staleChange;
  assert.equal(elements.all.hidden, true);
  show = elements.mine.onclick();
  reply(pending.shift(), false, {error: '请输入有效的演示凭据'});
  await show;
  assert.equal(elements.result.textContent, '请输入有效的演示凭据');
  console.log('Page script checks passed (role, own records, errors, stale responses).');
}
run().catch(error => {console.error(error); process.exitCode = 1;});

// Exercise the page's actual handlers without installing a browser dependency.
const {readFileSync} = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const html = readFileSync('index.html', 'utf8');
const elements = {
  key: {value: ''}, result: {textContent: ''}, all: {hidden: true}, mine: {}
};
const pending = [];
vm.runInNewContext(html.match(/<script>([\s\S]*?)<\/script>/)[1], {
  document: {getElementById: id => elements[id]},
  fetch: (path, options) => new Promise((resolve, reject) => {
    pending.push({path, options, resolve, reject});
  })
});
function reply(value, ok = true) {
  const request = pending.shift();
  request.resolve({ok, json: async () => value});
  return request;
}
(async () => {
  elements.key.value = 'synthetic-organizer-key';
  let input = elements.key.oninput();
  assert.equal(reply({role: 'organizer'}).path, '/api/session');
  await input;
  assert.equal(elements.all.hidden, false);
  let click = elements.all.onclick();
  assert.equal(reply([{id: 'synthetic-a'}, {id: 'synthetic-b'}]).path, '/api/all');
  await click;
  assert.match(elements.result.textContent, /synthetic-b/);
  elements.key.value = 'synthetic-member-key';
  input = elements.key.oninput();
  assert.equal(elements.result.textContent, '');
  assert.equal(elements.all.hidden, true);
  reply({role: 'member'});
  await input;
  click = elements.mine.onclick();
  const request = reply([{id: 'synthetic-a'}]);
  assert.equal(request.path, '/api/mine');
  assert.equal(request.options.headers['X-Demo-Key'], 'synthetic-member-key');
  await click;
  assert.match(elements.result.textContent, /synthetic-a/);
  click = elements.mine.onclick();
  reply({error: '凭据无效'}, false);
  await click;
  assert.equal(elements.result.textContent, '凭据无效');
  click = elements.mine.onclick();
  reply([]);
  await click;
  assert.equal(elements.result.textContent, '暂无报名记录');
  // An old role response or roster must not reappear after changing identity.
  const staleInput = elements.key.oninput();
  elements.key.value = '';
  await elements.key.oninput();
  reply({role: 'organizer'});
  await staleInput;
  assert.equal(elements.all.hidden, true);
  const staleClick = elements.all.onclick();
  await elements.key.oninput();
  reply([{id: 'stale-roster'}]);
  await staleClick;
  assert.equal(elements.result.textContent, '');
  click = elements.mine.onclick();
  pending.shift().reject(new Error('local service unavailable'));
  await click;
  assert.match(elements.result.textContent, /读取失败/);
  console.log('PASS: existing UI flow, server roles, errors, empty records, identity switching and stale responses');
})().catch(error => {console.error(error); process.exitCode = 1;});
